mapper.select:
SELECT  FROM ops_daily_close WHERE tenant_id=#{tenantId}
  AND store_id=#{storeId}
  AND business_date=#{businessDate}
ORDER BY business_date DESC,store_id,close_version DESC LIMIT #{limit}

mapper.update:
UPDATE ops_daily_close SET state=#{toState},preflight_run=COALESCE(#{preflightRun},preflight_run),
  snapshot_sha256=COALESCE(#{snapshotSha256},snapshot_sha256),manifest_sha256=COALESCE(#{manifestSha256},manifest_sha256),
  record_version=record_version+1,updated_at=#{at}
WHERE tenant_id=#{tenantId} AND close_id=#{closeId} AND state=#{fromState} AND record_version=#{expectedVersion}

mapper.select:
SELECT command_id commandId,close_id closeId,operation,idempotency_key idempotencyKey,
  request_sha256 requestSha256,result_state resultState,result_sha256 resultSha256,created_at createdAt
FROM ops_daily_close_command_result WHERE tenant_id=#{tenantId} AND operation=#{operation} AND idempotency_key=#{idempotencyKey}
